import{z as A,x as p,o as E,c as s,q as r,j as l,D as e,d as o,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"PDF / 扫描件进预训练","description":"","frontmatter":{"title":"PDF / 扫描件进预训练","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pdf-ocr-pretrain.md","filePath":"llm/pdf-ocr-pretrain.md","lastUpdated":1791413859000}'),B={name:"llm/pdf-ocr-pretrain.md"};function C(d,a,D,F,c,m){const t=p("Mermaid");return E(),s("div",null,[a[2]||(a[2]=r('<h1 id="pdf-扫描件进预训练" tabindex="-1">PDF / 扫描件进预训练 <a class="header-anchor" href="#pdf-扫描件进预训练" aria-label="Permalink to &quot;PDF / 扫描件进预训练&quot;">​</a></h1><div class="epigraph"><p>书籍与论文的知识经常锁在 PDF 里；不经校对的 OCR 会把栏序、公式和印刷噪声写成「语言」，模型学到的是扫描件的错误，而不是书。</p><footer>—— 学术 PDF 理解见 Blecher et al. Nougat；开放混合物中的论文源见 Soldaini Dolma</footer></div><p><a href="/llm/code-license-gate">上一课</a>让代码桶先过许可检测，再过生成文件 / 解析 / 近重复 / 密钥门；网页代码块不能借用 The Stack 的许可结论。网页配方处理的是 HTML；人类知识的另一大块写在 PDF 里。缺口是先区分数字原生文本层与仅图像扫描件，再用结构解析或 OCR，最后用与数学校对同构的门拦住乱码。本课写 PDF 进预训练，不重讲 SPDX。能拿到 TeX 或干净文本层时，不要走扫描件路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>许可门挡住的是仓库，挡不住教材与扫描旧刊。PDF 不是文本。它是绘图指令：字形位置、图片、矢量公式。数字原生 PDF 往往能抽出字符，但阅读顺序可能按印刷坐标而不是逻辑栏序，双栏论文会左右交错。扫描件只有光栅，必须 OCR。错误模式不同：文本层乱序是结构错误；OCR 是替换、切分与公式崩溃。二者都会进入 NTP，成为高置信的「拼写变体」。</p><p><span class="marginnote">术语翻译：NTP（next-token prediction）就是让模型逐字玩「猜下一个字」，语料里写什么它就把什么当事实学。所以扫描件的错字不会被理解为「错」，而是被当成一种新的拼写习惯照单全收——脏数据进的不是数据库，是语言习惯本身。</span></p><p>版式对象比新闻网页更丰富。页眉页脚、脚注、水印、参考文献、分栏、跨页表格，通用 Trafilatura 帮不上忙。数学与化学公式常是图。若用普通 OCR 引擎按行读，上下标消失，积分号变成噪声。预训练若大量吞下这种序列，会在科学域表现出「能说术语、不能写合法公式」。许可与来源同样成问题：影书扫描件、受版权保护的教材，不能因为 OCR 成功就进开放混合物。</p><h3 id="文本层优先于-ocr" tabindex="-1">文本层优先于 OCR <a class="header-anchor" href="#文本层优先于-ocr" aria-label="Permalink to &quot;文本层优先于 OCR&quot;">​</a></h3><p>数字原生 PDF 应先抽文本层并做栏序恢复（基于坐标聚类），只有文本层空洞、乱码或明显与页面图像不对齐时才 OCR。全程 OCR 更匀质，但更贵、更易引入系统性拼写错误。<span class="marginnote">「PDF 抽出来的字符数」与 HTML 抽取一样，不能当质量。扫描件 OCR 总是更长或更短得离谱。质检应看：栏序抽检、词错误率代理、公式解析率，以及是否残留页眉「第 n 页」在段落中间反复出现。</span></p><p>扫描质量决定上限。低 dpi、倾斜、装订阴影、双页对开被当成一页，任何神经 OCR 都会崩。管线应先做图像质检（分辨率、倾斜、对比度），不达标的页丢掉或降权，而不是全部塞进 Nougat。预训练不缺「更多坏书」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分流：有 TeX 源的论文走数学抽取篇的 TeX 路径；有结构化 XML 的出版商数据走 XML；其余 PDF 进入本文。数字原生：用 PDF 解析库提取带坐标的 span，按栏聚类恢复阅读顺序，表格用专用检测，页眉页脚用跨页重复度剥离。扫描件：版面分析（分栏、图、表）→ 区域 OCR 或整页 Nougat / Marker 一类学术模型 → 后处理。学术论文上，Nougat 的目标是恢复 Markup 与公式，而不是纯纯文本行；其输出仍要过解析与密度门。</p><p>校对门：语言识别（OCR 常把公式页判成错误语言）、异常字符率、字典 OOV 率、栏序启发式（是否在行末反复切断单词）、公式 KaTeX 通过率、页眉页脚重复 n-gram。通过后按文档级去重：同一书的多个扫描版、预印本与正式版。MinHash 应在 OCR 规范化（折叠空白、去连字符断行）之后做，否则同一页的两次扫描会被当成新文档。</p>',13)),(E(),l(n,null,{default:e(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PDF%5B%22PDF%22%5D%20--%3E%20T%7B%22%E6%9C%89%E5%8F%AF%E9%9D%A0%E6%96%87%E6%9C%AC%E5%B1%82%3F%22%7D%0A%20%20T%20--%3E%7C%E6%98%AF%7C%20LAY%5B%22%E5%9D%90%E6%A0%87%E6%A0%8F%E5%BA%8F%E6%81%A2%E5%A4%8D%22%5D%0A%20%20T%20--%3E%7C%E5%90%A6%7C%20IMG%5B%22%E5%9B%BE%E5%83%8F%E8%B4%A8%E6%A3%80%22%5D%0A%20%20IMG%20--%3E%20OCR%5B%22%E7%89%88%E9%9D%A2%20%2B%20OCR%20%2F%20Nougat%22%5D%0A%20%20LAY%20--%3E%20CHK%5B%22%E4%B9%B1%E5%BA%8F%20%2F%20%E9%A1%B5%E7%9C%89%20%2F%20%E5%85%AC%E5%BC%8F%E9%97%A8%22%5D%0A%20%20OCR%20--%3E%20CHK%0A%20%20CHK%20--%3E%20DED%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%E5%8E%BB%E9%87%8D%22%5D%0A%20%20DED%20--%3E%20MIX%5B%22%E4%B9%A6%E7%B1%8D%20%2F%20%E8%AE%BA%E6%96%87%E6%A1%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="神经-ocr-仍是有噪声的教师" tabindex="-1">神经 OCR 仍是有噪声的教师 <a class="header-anchor" href="#神经-ocr-仍是有噪声的教师" aria-label="Permalink to &quot;神经 OCR 仍是有噪声的教师&quot;">​</a></h3><p>Nougat 一类模型在学术版式上优于通用 OCR，但会幻觉章节标题、漏图表、在未见宏包上失败。它的错误比 Tesseract 更「像 LaTeX」，因而更难被启发式发现。必须用独立信号交叉：与文本层对齐的页应比较二者差异；仅图像页应抽样人工看，或与可获得的 HTML 版对拍。Dolma 选择 Semantic Scholar 处理好的 peS2o，是把校对前移到上游，而不是在预训练前夜对千万 PDF 现场 OCR。</p><p><span class="marginnote">HTML 抽取器与 PDF OCR 不要争同一文档的两个坏版本。能找到 arXiv HTML 或 TeX，就不要用出版社 PDF 的 OCR。跨源去重必须在混合物层做，否则 Dolma 的论文桶与 FineWeb 里转载的摘要会叠三份。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OCR 噪声使经验分布在真实词 \\(w\\) 的邻域上扩散出 \\(w&#39;\\)。模型同时学习 \\(w\\) 与 \\(w&#39;\\)，解码时二者竞争。若 \\(w&#39;\\) 在扫描语料中更频繁（系统性把 <code>rn</code> 认成 <code>m</code>），错误会赢。校对是把 \\(p(w&#39;)\\) 压回去。栏序错误则破坏长程依赖：左右栏交错相当于把两篇文章 zip 在一起，注意力学到的是虚假相邻。这比单字 OCR 错误更伤，因为局部 n-gram 仍像英语，KenLM 与 DCLM 头都可能放行。</p>',5)),(E(),l(n,null,{default:e(()=>[i(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20E1%5B%22OCR%20%E6%9B%BF%E6%8D%A2%E9%94%99%E8%AF%AF%EF%BC%9Arn%20%E8%A2%AB%E8%AE%A4%E6%88%90%20m%22%5D%20--%3E%20C%5B%22%E8%AF%AD%E6%96%99%E9%87%8C%E5%87%BA%E7%8E%B0%E9%94%99%E8%AF%8D%20w-prime%22%5D%0A%20%20C%20--%3E%20L%5B%22%E6%A8%A1%E5%9E%8B%E6%8A%8A%20w%20%E4%B8%8E%20w-prime%20%E4%B8%80%E8%B5%B7%E5%AD%A6%22%5D%0A%20%20L%20--%3E%20R%5B%22w-prime%20%E6%9B%B4%E9%A2%91%E7%B9%81%E6%97%B6%EF%BC%8C%E8%A7%A3%E7%A0%81%E6%97%B6%E9%94%99%E8%AF%AF%E8%83%9C%E5%87%BA%22%5D%0A%20%20E2%5B%22%E5%8F%8C%E6%A0%8F%E5%B7%A6%E5%8F%B3%E4%BA%A4%E9%94%99%22%5D%20--%3E%20Z%5B%22%E4%B8%A4%E6%A0%8F%E8%A2%AB%20zip%20%E6%88%90%E4%B8%80%E6%9D%A1%E5%BA%8F%E5%88%97%22%5D%0A%20%20Z%20--%3E%20F%5B%22%E5%B1%80%E9%83%A8%20n-gram%20%E4%BB%8D%E5%83%8F%E6%AD%A3%E5%B8%B8%E8%AF%AD%E8%A8%80%22%5D%0A%20%20F%20--%3E%20G%5B%22%E9%80%9A%E7%94%A8%E8%B4%A8%E9%87%8F%E5%A4%B4%E6%94%BE%E8%A1%8C%EF%BC%8C%E9%95%BF%E7%A8%8B%E4%BE%9D%E8%B5%96%E8%A2%AB%E6%82%84%E6%82%84%E7%A0%B4%E5%9D%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">直觉类比：栏序交错像把两本书每隔一行交替印刷——每一行单独读都通顺，相邻两行却毫无关系。这就是逐句打分的质检（KenLM、困惑度头）发现不了它的原因：错不在句子里，而在句子之间的顺序里。</span></p><p>公式 OCR 把数学支撑从可解析集合里拖出。与数学抽取篇相同：解析门应成为科学 PDF 的硬条件。对纯人文扫描件，公式门可关，但栏序与页眉门仍要开。语言识别应在校对之后：OCR 乱码会被 lid 标成「未知」丢掉，看起来像过滤，其实是扫描失败。</p><h3 id="与网页、合成数据的配比" tabindex="-1">与网页、合成数据的配比 <a class="header-anchor" href="#与网页、合成数据的配比" aria-label="Permalink to &quot;与网页、合成数据的配比&quot;">​</a></h3><p>PDF 桶信息密度高、文体旧、版权风险高。它不能按 token 与 FineWeb 对等比较。应用文档数或「有效干净页」计量，并设上限，以免旧刊文体支配生成。合成改写（把 OCR 输出交给 LM 润色）能降噪声，但会引入教师腔，且可能把错误「通顺化」——错误被改成语法正确的错事实。有源校对优于无源润色：能对齐到文本层或 TeX 的，不要用 LM 改写冒充干净书。</p><p><span class="marginnote">常见误区：以为让 LM 把 OCR 输出润色一遍就等于校对。润色会把错误「通顺化」——错的年份、错的公式被改写成语法优美的错事实，比原始乱码更难察觉。只要还能对齐到文本层或 TeX，就优先有源校对，别让另一个模型凭空改写。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>版权是硬边界。Gutenberg 一类公有领域、明确开放的论文源，才适合开放配方。来源不明的「Books」扫描件不应出现在声称可审计的混合物里。即使法律允许，扫描件的伦理与退出机制也要写进数据卡片。多语言 OCR 模型质量差距大，低资源扫描件应更依赖数字原生文本层，或干脆不进预训练。</p><p>成本：神经 OCR 每页的计算可能高于训练时读该页。应只对高价值、无文本层的页使用。存储 PDF 原件以便将来换 OCR 引擎重抽，比只存一份脏文本更符合「配方可修订」。FineWeb 不包含这一桶，并不意味着网页已覆盖书中知识；意味着网页配方拒绝为脏 OCR 买单。把 PDF 加进来是新的配方决策，不是默认下一步。</p><p><span class="marginnote">不要用维基 KenLM 给 OCR 输出打分来当质检。通顺的错字对 \\(n\\)-gram LM 仍然低困惑。OOV、公式解析、栏序抽检才是 PDF 专用门。CCNet 的质量定义在这里不适用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PDF 进预训练必须分流：TeX / 文本层优先，扫描件才 OCR。</li><li>栏序错误比单字错误更阴险，通用网页质量头看不见。</li><li>Nougat 等神经 OCR 会产出「像 LaTeX 的错」，仍要独立校对。</li><li>规范化后再去重；跨源不要与 HTML / arXiv 叠脏副本。</li><li>版权与图像质检是硬门；宁缺毋脏。</li><li>Dolma 式论文源把结构处理放在上游，优于现场盲 OCR。</li><li>出处：Blecher et al.，Nougat；Soldaini et al.，Dolma / peS2o；网页上限对照 Penedo FineWeb 与 Trafilatura / Resiliparse；勿套用 Wenzek CCNet 困惑度当 OCR 质检。</li></ul>',11))])}const T=A(B,[["render",C]]);export{P as __pageData,T as default};
